INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 1, 24001, 1, 102601, "2020/04/30 12:00:00", "あたしだって\nやるときはやるよ！", "リン", 0, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 1, 24002, 1, 102601, "2020/04/30 12:00:00", "ふぅ…\nこれであたしの仕事は\n終わりだね", "リン", 1, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 1, 24003, 1, 102601, "2020/04/30 12:00:00", "終わった終わった\n一人でもなんとか\nなるもんだね", "リン", 2, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 2, 24004, 2, 102601, "2020/04/30 12:00:00", "やったね！\nこれでようやく\nサボれるよ…", "リン", 3, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 1, 24005, 1, 102601, "2020/04/30 12:00:00", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", "リン", 4, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 2, 24006, 2, 102601, "2020/04/30 12:00:00", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", "リン", 5, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 2, 24007, 2, 102601, "2020/04/30 12:00:00", "あたしも意外と\nやるもんでしょ？", "リン", 6, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 4, 24008, 4, 102601, "2020/04/30 12:00:00", "疲れた…\nねずみの逃げ足\n速すぎるよ…", "リン", 7, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 4, 24009, 4, 102601, "2020/04/30 12:00:00", "このままじゃ\nまっひ～に\n叱られちゃうよ", "リン", 8, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 4, 24010, 4, 102601, "2020/04/30 12:00:00", "まじめに\nやったんだけどな…\n悔しいな～", "リン", 9, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 4, 24011, 4, 102601, "2020/04/30 12:00:00", "やられた…\nねずみって意外と\nてごわいね", "リン", 10, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (0.0, 10040, "2030/12/17 14:59:59", 0.0, 4, 24012, 4, 102601, "2020/04/30 12:00:00", "おのれ～\nあたしのチーズを\n盗みやがって～！", "リン", 11, 0.0, 24);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (1.81, 10040, "2030/12/17 14:59:59", 0.0, 4, 24013, 1, 102601, "2020/04/30 12:00:00", "疲れた…\nけど、次こそは\n守り抜くよ…", "リン", 12, 0.0, 24);
